using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using Shop.Domain.Catalog;

namespace Shop.Features.Catalog;

// Module-level mapping, outside any slice: the domain stays free of EF Core attributes and references.
// AppDbContext applies it by itself; each change of the mapping needs a migration.
internal sealed class ProductConfiguration : IEntityTypeConfiguration<Product>
{
    public void Configure(EntityTypeBuilder<Product> builder)
    {
        builder.ToTable("Products");

        builder.HasKey(aggregate => aggregate.Id);
        builder.Property(aggregate => aggregate.Id)
            .HasConversion(id => id.Value, value => new ProductId(value))
            .ValueGeneratedNever();

        builder.Ignore(aggregate => aggregate.DomainEvents);
    }
}
using Shop.Domain.Catalog;

namespace Shop.Tests.Domain.Catalog;

public sealed class ProductTests
{
    [Fact]
    public void Create_gives_the_new_Product_its_state()
    {
        var aggregate = Product.Create();

        aggregate.Id.Value.ShouldNotBe(Guid.Empty);
        Assert.Fail("TODO(hardslice): pass the state of the new Product to its factory method, assert it here, "
            + "then test each rule that the factory refuses with Should.Throw<DomainException>.");
    }

    [Fact]
    public void Create_gives_each_Product_its_own_identifier()
    {
        Product.Create().Id.ShouldNotBe(Product.Create().Id);
    }

    [Fact]
    public void DequeueDomainEvents_returns_the_raised_events_once_and_empties_the_list()
    {
        var aggregate = Product.Create();
        var raised = aggregate.DomainEvents.ToArray();

        aggregate.DequeueDomainEvents().ShouldBe(raised);
        aggregate.DomainEvents.ShouldBeEmpty();
        aggregate.DequeueDomainEvents().ShouldBeEmpty();
    }
}
